import logging
from ute_common_abstract_core import logger as core_logging  # type: ignore


def configure_main_logger(logger_name):
    """Configure main logger"""
    core_logging.create_logger(
        name=logger_name,
        log_file=f"{logger_name}.log",
        log_level=logging.DEBUG,
        log_format="%(asctime)s | %(name)-40s | %(levelname)-8s | %(threadName)-23s | "
        "%(message)s /// %(funcName)s::%(filename)s(%(lineno)d)",
    )
    logger = logging.getLogger(logger_name)
    logger.propagate = False


def configure_msg_source_logger(logger_name):
    """Configure msg source logger"""
    core_logging.create_logger(
        name=logger_name,
        log_file=f"pmi_ticket_collector_{logger_name}.log",
        log_level=logging.DEBUG,
        log_format="%(asctime)s | %(name)-13s | %(levelname)-8s | %(threadName)-12s | " "%(message)s",
    )
    logger = logging.getLogger(logger_name)
    logger.propagate = False
